    const apiUrl = process.env.NEXT_PUBLIC_STEM_BOT_API_URL;
    const token = process.env.STEM_BOT_API_BEARER_TOKEN;

    console.log(`[Discord Bot] Attempting to sync roles for discord_uid: ${discordUid}`);

